withr::local_dir(Sys.getenv('WYB_ROOT'))
testthat::test_that('shot publication preserves existing rows, rejects conflicts and resumes idempotently', {
  path<-tempfile(fileext='.duckdb');on.exit(unlink(path),add=TRUE)
  stage<-connect_warehouse(path);shot_recovery_schema(stage)
  ingest_bundle(stage,readRDS('data/sample/bundle.rds'),'2024-25')
  DBI::dbExecute(stage,"INSERT INTO shot_recovery_candidates (season,game_id,event_id,source_row,source_dataset_id,canonical_event_dataset_id,player_id,team_id,period,clock,event_order,made,points_attempted,value_status,classification_rule,coordinate_status,coordinate_system,certification_status,reason,dataset_id) SELECT g.season,s.game_id,s.event_id,row_number() OVER(ORDER BY s.game_id,s.event_id),s.dataset_id,s.dataset_id,s.player_id,s.team_id,e.period,e.clock,e.event_order,s.made,s.points_attempted,'observed','source_attempt_annotation','source_missing','source_frame_unverified','certified','','shot-recovery:test' FROM shot_attempts s JOIN games g USING(game_id) JOIN pbp_events e USING(game_id,event_id)")
  for(metric in c('fga','fgm','fg3a','fg3m'))DBI::dbExecute(stage,paste0("INSERT INTO shot_recovery_checks SELECT g.season,t.game_id,t.team_id,'",metric,"',t.",metric,",t.",metric,",'match','shot-recovery:test' FROM team_box_scores t JOIN games g USING(game_id)"))
  DBI::dbExecute(stage,"INSERT INTO shot_recovery_checkpoints VALUES ('2024-25','test-signature','test-method',1,current_timestamp)")
  d<-DBI::dbReadTable(stage,'datasets')[1,];d$dataset_id<-'shot-recovery:test:candidates';DBI::dbAppendTable(stage,'datasets',d)
  n<-DBI::dbGetQuery(stage,'SELECT count(*) n FROM shot_attempts')$n
  DBI::dbDisconnect(stage,shutdown=TRUE)
  con<-connect_warehouse(':memory:');on.exit(DBI::dbDisconnect(con,shutdown=TRUE))
  ingest_bundle(con,readRDS('data/sample/bundle.rds'),'2024-25')
  keep<-DBI::dbGetQuery(con,'SELECT * FROM shot_attempts ORDER BY game_id,event_id LIMIT 1');manifests<-DBI::dbReadTable(con,'datasets')
  DBI::dbExecute(con,'DELETE FROM shot_attempts WHERE event_id!=?',params=list(keep$event_id))
  testthat::expect_equal(publish_shot_recovery(con,path),n-1)
  testthat::expect_equal(publish_shot_recovery(con,path),0)
  testthat::expect_identical(DBI::dbGetQuery(con,'SELECT * FROM shot_attempts WHERE event_id=?',params=list(keep$event_id)),keep)
  testthat::expect_true(all(shot_recovery_integrity(con)$passed))
  testthat::expect_identical(DBI::dbReadTable(con,'datasets')[match(manifests$dataset_id,DBI::dbReadTable(con,'datasets')$dataset_id),],manifests)
  DBI::dbExecute(con,'UPDATE shot_attempts SET made=NOT made WHERE event_id=?',params=list(keep$event_id))
  conflict<-DBI::dbGetQuery(con,'SELECT * FROM shot_attempts WHERE event_id=?',params=list(keep$event_id))
  testthat::expect_equal(publish_shot_recovery(con,path),0)
  testthat::expect_identical(DBI::dbGetQuery(con,'SELECT * FROM shot_attempts WHERE event_id=?',params=list(keep$event_id)),conflict)
  testthat::expect_equal(DBI::dbGetQuery(con,'SELECT count(*) n FROM certified_shot_attempts WHERE game_id=?',params=list(keep$game_id))$n,0)
  testthat::expect_equal(DBI::dbGetQuery(con,'SELECT count(*) n FROM shot_publication_conflicts')$n,1)
  DBI::dbExecute(con,'UPDATE shot_attempts SET made=NOT made WHERE event_id=?',params=list(keep$event_id))
  DBI::dbExecute(con,'UPDATE player_box_scores SET did_not_play=TRUE WHERE game_id=? AND player_id=?',params=list(keep$game_id,keep$player_id))
  publish_shot_recovery(con,path)
  testthat::expect_equal(DBI::dbGetQuery(con,'SELECT count(*) n FROM certified_shot_attempts WHERE game_id=?',params=list(keep$game_id))$n,0)
  testthat::expect_equal(DBI::dbGetQuery(con,'SELECT count(*) n FROM shot_attempts WHERE game_id=?',params=list(keep$game_id))$n,1)
})
